 JavaScript Implementáció

javascript
// ==== DOM ELEMEK REFERENCIÁK ====
const historyPanel = document.getElementById('historyPanel');
const panelOverlay = document.getElementById('panelOverlay');
const openHistoryBtn = document.getElementById('openHistoryBtn');
const closeHistoryBtn = document.getElementById('closeHistoryBtn');
const mainView = document.getElementById('main-chat-view');

// ==== ÁLLAPOT KEZELÉS ====
let isPanelOpen = false;

// ==== PANEL MEGNYITÁSA ====
function openHistoryPanel() {
  isPanelOpen = true;

  // Panel slide-in animáció
  historyPanel.classList.add('open');

  // Overlay megjelenítés
  panelOverlay.classList.add('active');

  // Body scroll letiltás (panel nyitva van)
  document.body.style.overflow = 'hidden';

  // Accessibility attributumok
  historyPanel.setAttribute('aria-hidden', 'false');
  panelOverlay.setAttribute('aria-hidden', 'false');

  // Focus a bezárás gombra (keyboard navigation)
  setTimeout(() => {
    closeHistoryBtn.focus();
  }, 100);

  console.log('History panel megnyitva');
}

// ==== PANEL BEZÁRÁSA ====
function closeHistoryPanel() {
  isPanelOpen = false;

  // Panel slide-out animáció
  historyPanel.classList.remove('open');

  // Overlay elrejtés
  panelOverlay.classList.remove('active');

  // Body scroll visszaállítás
  document.body.style.overflow = '';

  // Accessibility
  historyPanel.setAttribute('aria-hidden', 'true');
  panelOverlay.setAttribute('aria-hidden', 'true');

  // Focus vissza a megnyitás gombra
  openHistoryBtn.focus();

  console.log('History panel bezárva');
}

// ==== TOGGLE FUNKCIÓ ====
function toggleHistoryPanel() {
  if (isPanelOpen) {
    closeHistoryPanel();
  } else {
    openHistoryPanel();
  }
}

// ==== EVENT LISTENERS ====
// Megnyitás gomb click
openHistoryBtn.addEventListener('click', (e) => {
  e.stopPropagation();
  openHistoryPanel();
});

// Bezárás gomb click
closeHistoryBtn.addEventListener('click', (e) => {
  e.stopPropagation();
  closeHistoryPanel();
});

// Overlay click = bezárás
panelOverlay.addEventListener('click', () => {
  closeHistoryPanel();
});

// ESC billentyű kezelés
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && isPanelOpen) {
    closeHistoryPanel();
  }
});

// Panel-en belüli click ne zárja be
historyPanel.addEventListener('click', (e) => {
  e.stopPropagation();
});

// ==== MOBIL SWIPE GESTURE ====
let touchStartX = 0;
let touchEndX = 0;
let touchStartTime = 0;

historyPanel.addEventListener('touchstart', (e) => {
  touchStartX = e.changedTouches[0].screenX;
  touchStartTime = Date.now();
}, { passive: true });

historyPanel.addEventListener('touchmove', (e) => {
  touchEndX = e.changedTouches[0].screenX;
}, { passive: true });

historyPanel.addEventListener('touchend', (e) => {
  const swipeDistance = touchEndX - touchStartX;
  const swipeTime = Date.now() - touchStartTime;
  const swipeVelocity = Math.abs(swipeDistance) / swipeTime;

  // Balra swipe = bezárás (min 50px vagy gyors swipe)
  if (swipeDistance < -50 || (swipeDistance < -20 && swipeVelocity > 0.5)) {
    closeHistoryPanel();
  }
}, { passive: true });

// ==== THREAD ADATOK (példa) ====
const threadsData = [
  {
    id: 1,
    title: "Machine learning alapok",
    preview: "Mi az a neurális háló és hogyan működik...",
    timestamp: new Date(),
  },
  {
    id: 2,
    title: "Frontend fejlesztés 2026",
    preview: "React vs Vue összehasonlítás modern...",
    timestamp: new Date(Date.now() - 3600000), // 1 óra
  },
  {
    id: 3,
    title: "Python adatstruktúrák",
    preview: "List, tuple, dict használata és...",
    timestamp: new Date(Date.now() - 86400000), // 1 nap
  },
  {
    id: 4,
    title: "CSS Grid layout példák",
    preview: "Hogyan építsünk responsive grid...",
    timestamp: new Date(Date.now() - 172800000), // 2 nap
  }
];

// ==== THREAD CSOPORTOSÍTÁS DÁTUM SZERINT ====
function groupThreadsByDate(threads) {
  const groups = {
    today: [],
    yesterday: [],
    last7days: [],
    last30days: [],
    older: []
  };

  const now = new Date();
  const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const yesterdayStart = new Date(todayStart);
  yesterdayStart.setDate(yesterdayStart.getDate() - 1);
  const last7Start = new Date(todayStart);
  last7Start.setDate(last7Start.getDate() - 7);
  const last30Start = new Date(todayStart);
  last30Start.setDate(last30Start.getDate() - 30);

  threads.forEach(thread => {
    const threadDate = new Date(thread.timestamp);

    if (threadDate >= todayStart) {
      groups.today.push(thread);
    } else if (threadDate >= yesterdayStart) {
      groups.yesterday.push(thread);
    } else if (threadDate >= last7Start) {
      groups.last7days.push(thread);
    } else if (threadDate >= last30Start) {
      groups.last30days.push(thread);
    } else {
      groups.older.push(thread);
    }
  });

  return groups;
}

// ==== THREAD LISTA RENDERELÉS ====
function renderThreadsList() {
  const threadsListContainer = document.querySelector('.threads-list');
  if (!threadsListContainer) return;

  threadsListContainer.innerHTML = '';

  const groupedThreads = groupThreadsByDate(threadsData);

  const groupLabels = {
    today: 'Ma',
    yesterday: 'Tegnap',
    last7days: 'Elmúlt 7 nap',
    last30days: 'Elmúlt 30 nap',
    older: 'Régebbi'
  };

  Object.keys(groupLabels).forEach(groupKey => {
    const threads = groupedThreads[groupKey];
    if (threads.length === 0) return;

    const groupDiv = document.createElement('div');
    groupDiv.className = 'thread-group';

    const heading = document.createElement('h3');
    heading.textContent = groupLabels[groupKey];
    groupDiv.appendChild(heading);

    threads.forEach(thread => {
      const threadItem = createThreadItem(thread);
      groupDiv.appendChild(threadItem);
    });

    threadsListContainer.appendChild(groupDiv);
  });
}

// ==== THREAD ELEM LÉTREHOZÁS ====
function createThreadItem(thread) {
  const div = document.createElement('div');
  div.className = 'thread-item';
  div.setAttribute('data-thread-id', thread.id);

  // Ha ez az aktív thread
  if (thread.id === getCurrentThreadId()) {
    div.classList.add('active');
  }

  const title = document.createElement('div');
  title.className = 'thread-title';
  title.textContent = thread.title;

  const preview = document.createElement('div');
  preview.className = 'thread-preview';
  preview.textContent = thread.preview;

  div.appendChild(title);
  div.appendChild(preview);

  // Click event - thread betöltése
  div.addEventListener('click', () => {
    loadThread(thread.id);
    closeHistoryPanel();
  });

  return div;
}

// ==== THREAD BETÖLTÉS ====
function loadThread(threadId) {
  console.log('Thread betöltés:', threadId);

  // TODO: Implementáld a thread betöltését
  // - Töröld az aktuális chat history-t
  // - Töltsd be a thread üzeneteit
  // - Frissítsd az UI-t

  // Active state frissítés
  updateActiveThread(threadId);
}

function updateActiveThread(threadId) {
  document.querySelectorAll('.thread-item').forEach(item => {
    item.classList.remove('active');
  });

  const activeItem = document.querySelector(`[data-thread-id="${threadId}"]`);
  if (activeItem) {
    activeItem.classList.add('active');
  }
}

function getCurrentThreadId() {
  // Visszaadja az aktuális thread ID-t
  return localStorage.getItem('currentThreadId') || null;
}

// ==== THREAD KERESÉS ====
const searchInput = document.querySelector('.search-threads input');
if (searchInput) {
  searchInput.addEventListener('input', (e) => {
    const query = e.target.value.toLowerCase().trim();
    filterThreads(query);
  });
}

function filterThreads(query) {
  if (!query) {
    // Ha üres a keresés, mutass mindent
    document.querySelectorAll('.thread-item, .thread-group').forEach(el => {
      el.style.display = '';
    });
    return;
  }

  document.querySelectorAll('.thread-item').forEach(item => {
    const title = item.querySelector('.thread-title').textContent.toLowerCase();
    const preview = item.querySelector('.thread-preview').textContent.toLowerCase();

    if (title.includes(query) || preview.includes(query)) {
      item.style.display = '';
    } else {
      item.style.display = 'none';
    }
  });

  // Üres csoportok elrejtése
  document.querySelectorAll('.thread-group').forEach(group => {
    const visibleItems = group.querySelectorAll('.thread-item:not([style*="display: none"])');
    group.style.display = visibleItems.length > 0 ? '' : 'none';
  });
}

// ==== INICIALIZÁLÁS ====
document.addEventListener('DOMContentLoaded', () => {
  // Thread lista renderelés
  renderThreadsList();

  // Accessibility attributes
  historyPanel.setAttribute('aria-hidden', 'true');
  panelOverlay.setAttribute('aria-hidden', 'true');

  // LocalStorage-ból thread-ek betöltése
  loadThreadsFromStorage();

  console.log('History panel inicializálva');
});

// ==== LOCALSTORAGE KEZELÉS ====
function saveThreadsToStorage() {
  localStorage.setItem('threads', JSON.stringify(threadsData));
}

function loadThreadsFromStorage() {
  const stored = localStorage.getItem('threads');
  if (stored) {
    try {
      const parsed = JSON.parse(stored);
      threadsData.length = 0;
      threadsData.push(...parsed);
      renderThreadsList();
    } catch (e) {
      console.error('Hiba a thread-ek betöltésekor:', e);
    }
  }
}

// ==== ÚJ THREAD HOZZÁADÁSA ====
function addNewThread(title, firstMessage) {
  const newThread = {
    id: Date.now(),
    title: title || 'Új beszélgetés',
    preview: firstMessage ? firstMessage.substring(0, 60) + '...' : 'Új beszélgetés',
    timestamp: new Date()
  };

  threadsData.unshift(newThread);
  saveThreadsToStorage();
  renderThreadsList();

  return newThread.id;
}

// ==== THREAD TÖRLÉS ====
function deleteThread(threadId) {
  const index = threadsData.findIndex(t => t.id === threadId);

  if (index > -1) {
    const confirmDelete = confirm('Biztosan törölni szeretnéd ezt a beszélgetést?');

    if (confirmDelete) {
      threadsData.splice(index, 1);
      saveThreadsToStorage();
      renderThreadsList();
      console.log('Thread törölve:', threadId);
    }
  }
}

// ==== WINDOW RESIZE KEZELÉS ====
