javascript
document.addEventListener('contextmenu', (e) => {
  const threadItem = e.target.closest('.thread-item');
  if (threadItem) {
    e.preventDefault();
    const threadId = parseInt(threadItem.dataset.threadId);
    showContextMenu(e.clientX, e.clientY, threadId);
  }
});

function showContextMenu(x, y, threadId) {
  // Context menu HTML létrehozása
  const menu = document.createElement('div');
  menu.className = 'context-menu';
  menu.style.left = x + 'px';
  menu.style.top = y + 'px';
  menu.innerHTML = `
    <div class="menu-item" data-action="rename">Átnevezés</div>
    <div class="menu-item" data-action="share">Megosztás</div>
    <div class="menu-item" data-action="delete">Törlés</div>
  `;

  document.body.appendChild(menu);

  // Event listeners a menüpontokon
  menu.querySelectorAll('.menu-item').forEach(item => {
    item.addEventListener('click', () => {
      const action = item.dataset.action;
      handleContextAction(action, threadId);
      menu.remove();
    });
  });

  // Bezárás click-re
  document.addEventListener('click', () => menu.remove(), { once: true });
}


