 JavaScript Módosítások

A swipe gesture irányának megfordítása kritikus:[4]

javascript
// ==== SWIPE GESTURE - JOBBRÓL BALRA ==== 
let touchStartX = 0;
let touchEndX = 0;
let touchStartTime = 0;
let isDragging = false;

historyPanel.addEventListener('touchstart', (e) => {
  touchStartX = e.changedTouches[0].screenX;
  touchStartTime = Date.now();
  isDragging = true;
}, { passive: true });

historyPanel.addEventListener('touchmove', (e) => {
  if (!isDragging) return;

  touchEndX = e.changedTouches[0].screenX;
  const dragDistance = touchEndX - touchStartX;

  // ⚠️ FONTOS: Csak jobbra húzás (pozitív = bezárás)
  if (dragDistance > 0) {
    const translateAmount = Math.min(dragDistance, window.innerWidth);
    historyPanel.style.transform = `translateX(${translateAmount}px)`;
  }
}, { passive: true });

historyPanel.addEventListener('touchend', (e) => {
  if (!isDragging) return;

  const swipeDistance = touchEndX - touchStartX;
  const swipeTime = Date.now() - touchStartTime;
  const swipeVelocity = Math.abs(swipeDistance) / swipeTime;

  // ⚠️ VÁLTOZÁS: JOBBRA swipe (pozitív irány) = bezárás
  if (swipeDistance > 50 || (swipeDistance > 20 && swipeVelocity > 0.5)) {
    closeHistoryPanel();
  } else {
    // Snap vissza
    historyPanel.style.transform = '';
  }

  isDragging = false;
}, { passive: true });


 Panel Megnyitás/Bezárás

