  if (!isPanelOpen) return;
  isPanelOpen = false;

  historyPanel.classList.add('closing');  // Gyorsabb bezárás
  historyPanel.classList.remove('open', 'bounce', 'elastic');

  panelOverlay.classList.remove('active');
  document.body.style.overflow = '';

  setTimeout(() => {
    historyPanel.classList.remove('closing');
  }, 300);

  console.log('❌ Panel bezárva');
}




 Desktop Drag Support (Bonus)

