let mouseStartX = 0;
let isMouseDragging = false;

historyPanel.addEventListener('mousedown', (e) => {
  // Panel bal széle (első 20px) fogható
  if (e.offsetX < 20) {
    mouseStartX = e.clientX;
    isMouseDragging = true;
    historyPanel.style.cursor = 'grabbing';
  }
});

document.addEventListener('mousemove', (e) => {
  if (!isMouseDragging) return;

  const dragDistance = e.clientX - mouseStartX;

  // Csak jobbra húzás
  if (dragDistance > 0) {
    historyPanel.style.transform = `translateX(${dragDistance}px)`;
  }
});

document.addEventListener('mouseup', () => {
  if (!isMouseDragging) return;

  const dragDistance = mouseEndX - mouseStartX;

  // 30% fölé húzva = bezárás
  if (dragDistance > window.innerWidth * 0.3) {
    closeHistoryPanel();
  } else {
    historyPanel.style.transform = '';
  }

  isMouseDragging = false;
  historyPanel.style.cursor = '';
});




