  <script>
    //  ELEM REFERENCIÁK 
    const panelTrigger = document.getElementById('panelTrigger');
    const panelClose = document.getElementById('panelClose');
    const slidingPanel = document.getElementById('slidingPanel');
    const panelBackdrop = document.getElementById('panelBackdrop');

    const chatInput = document.getElementById('chatInput');
    const sendBtn = document.getElementById('sendBtn');
    const chatHistory = document.getElementById('chatHistory');
    const navItems = document.querySelectorAll('.navitem[datatarget]');
    const views = document.querySelectorAll('.view');
    const toastEl = document.getElementById('toast');

    //  PANEL LOGIKA (SLIDEIN) 
    function openPanel() {
      slidingPanel.classList.add('open');
      panelBackdrop.classList.add('active');
    }

    function closePanel() {
      slidingPanel.classList.remove('open');
      panelBackdrop.classList.remove('active');
    }

    panelTrigger.addEventListener('click', openPanel);
    panelClose.addEventListener('click', closePanel);
    panelBackdrop.addEventListener('click', closePanel);

    // Escape gomb bezárja a panelt
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && slidingPanel.classList.contains('open')) {
        closePanel();
      }
    });

    //  NAVIGÁCIÓ 
    navItems.forEach(item => {
      item.addEventListener('click', () => {
        // Aktív osztály kezelése
        navItems.forEach(n => n.classList.remove('active'));
        item.classList.add('active');

        // Nézet váltás
        const target = item.getAttribute('datatarget');
        views.forEach(v => v.classList.remove('active'));
        document.getElementById(view-${target}).classList.add('active');

        // Mobilon (és alapból is a modern UX miatt) zárjuk be a panelt kattintás után
        closePanel();
      });
    });

    //  CHAT LOGIKA 
    function autoResize() {
      chatInput.style.height = 'auto';
      chatInput.style.height = chatInput.scrollHeight + 'px';

      if (chatInput.value.trim().length > 0) {
        sendBtn.removeAttribute('disabled');
        sendBtn.style.opacity = '1';
        sendBtn.style.cursor = 'pointer';
      } else {
        sendBtn.setAttribute('disabled', 'true');
        sendBtn.style.opacity = '0.3';
        sendBtn.style.cursor = 'default';
      }
    }

    chatInput.addEventListener('input', autoResize);

    function showToast(msg) {
      toastEl.textContent = msg;
      toastEl.classList.add('visible');
      setTimeout(() => toastEl.classList.remove('visible'), 2000);
    }

    function sendMessage() {
      const text = chatInput.value.trim();
      if (!text) return;

      // User üzenet
      const userMsg = document.createElement('div');
      userMsg.className = 'message user';
      userMsg.textContent = text;
      chatHistory.appendChild(userMsg);

      // Input reset
      chatInput.value = '';
      autoResize();
      chatHistory.scrollTo({ top: chatHistory.scrollHeight, behavior: 'smooth' });

      // AI válasz szimuláció
      setTimeout(() => {
        const aiMsg = document.createElement('div');
        aiMsg.className = 'message ai';
        aiMsg.innerHTML = 
          <div class="aiavatar"></div>
          <div>Ez egy automata válasz a demó felületen. <br>Ezt írtad: "<i>${text}</i>"</div>
        ;
        chatHistory.appendChild(aiMsg);
        chatHistory.scrollTo({ top: chatHistory.scrollHeight, behavior: 'smooth' });
      }, 600);
    }

    sendBtn.addEventListener('click', sendMessage);
    chatInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        sendMessage();
      }
    });

    // Új chat gomb
    document.getElementById('newChatBtn').addEventListener('click', () => {
      chatHistory.innerHTML = 
        <div class="message ai">
          <div class="aiavatar"></div>
          <div>Szia! Miben segíthetek ma?</div>
        </div>
      ;
      showToast('Új beszélgetés indítva');
      closePanel();
    });

    document.getElementById('clearHistoryBtn').addEventListener('click', () => {
       showToast('Előzmények törölve (demo)');
    });

  </script>
</body>
</html>

